export function validate(event) {
  if (!event || typeof event !== 'object' || typeof event.id !== 'string' || !event.id.trim()) throw new Error('invalid id');
  if (event.type === 'shipment.created') {
    if (typeof event.address !== 'string' || !event.address.trim()) throw new Error('invalid address');
  } else if (event.type === 'shipment.cancelled') {
    if (typeof event.reason !== 'string' || !event.reason.trim()) throw new Error('invalid reason');
    if (!Number.isSafeInteger(event.revision) || event.revision < 0) throw new Error('invalid revision');
  } else {
    throw new Error('unknown event');
  }
  return {...event};
}

