DEFAULTS = {'endpoint': 'http://localhost', 'retry': {'attempts': 3, 'delay_ms': 100}, 'tags': []}


def _validate_integer(value, name, minimum, maximum):
    if (isinstance(value, bool) or not isinstance(value, int)
            or not minimum <= value <= maximum):
        raise ValueError(f'{name} must be an integer in {minimum}..{maximum}')


def _validate_overrides(overrides):
    if not isinstance(overrides, dict):
        raise ValueError('overrides must be a dict')
    if overrides.keys() - {'endpoint', 'retry', 'tags'}:
        raise ValueError('unknown settings key')
    if 'endpoint' in overrides:
        endpoint = overrides['endpoint']
        if not isinstance(endpoint, str) or not endpoint:
            raise ValueError('endpoint must be a nonempty string')
    if 'retry' in overrides:
        retry = overrides['retry']
        if not isinstance(retry, dict):
            raise ValueError('retry must be a dict')
        if retry.keys() - {'attempts', 'delay_ms'}:
            raise ValueError('unknown retry key')
        if 'attempts' in retry:
            _validate_integer(retry['attempts'], 'attempts', 1, 10)
        if 'delay_ms' in retry:
            _validate_integer(retry['delay_ms'], 'delay_ms', 0, 60000)
    if 'tags' in overrides:
        tags = overrides['tags']
        if not isinstance(tags, list) or any(not isinstance(tag, str) for tag in tags):
            raise ValueError('tags must be a list of strings')


def _parse_attempts(value):
    if not isinstance(value, str) or not value.isdecimal():
        raise ValueError('APP_ATTEMPTS must be a decimal-digit string')
    # Parse incrementally to support leading zeros without an integer size limit.
    attempts = 0
    for digit in value:
        attempts = attempts * 10 + int(digit)
        if attempts > 10:
            raise ValueError('APP_ATTEMPTS must represent an integer in 1..10')
    _validate_integer(attempts, 'APP_ATTEMPTS', 1, 10)
    return attempts


def load_settings(overrides=None, env=None):
    if overrides is None:
        overrides = {}
    _validate_overrides(overrides)

    environment = {}
    if env is not None:
        if 'APP_ENDPOINT' in env:
            environment['endpoint'] = env['APP_ENDPOINT']
        if 'APP_ATTEMPTS' in env:
            environment['retry'] = {'attempts': _parse_attempts(env['APP_ATTEMPTS'])}
    _validate_overrides(environment)

    result = deepcopy(DEFAULTS)
    for layer in (overrides, environment):
        for key, value in layer.items():
            if key == 'retry':
                result['retry'].update(value)
            else:
                result[key] = deepcopy(value)
    return result

