def _validate_endpoint(value):
    if not isinstance(value, str) or not value:
        raise ValueError('endpoint must be a nonempty string')


def _validate_integer(value, name, minimum, maximum):
    if isinstance(value, bool) or not isinstance(value, int) or not minimum <= value <= maximum:
        raise ValueError(f'{name} must be an integer from {minimum} to {maximum}')


def load_settings(overrides=None, env=None):
    result = deepcopy(DEFAULTS)
    if overrides is not None:
        if not isinstance(overrides, dict) or overrides.keys() - DEFAULTS.keys():
            raise ValueError('overrides must be a dict with supported keys')
        if 'endpoint' in overrides:
            _validate_endpoint(overrides['endpoint'])
            result['endpoint'] = overrides['endpoint']
        if 'retry' in overrides:
            retry = overrides['retry']
            if not isinstance(retry, dict) or retry.keys() - DEFAULTS['retry'].keys():
                raise ValueError('retry must be a dict with supported keys')
            for name, minimum, maximum in [('attempts', 1, 10), ('delay_ms', 0, 60000)]:
                if name in retry:
                    _validate_integer(retry[name], name, minimum, maximum)
                    result['retry'][name] = retry[name]
        if 'tags' in overrides:
            tags = overrides['tags']
            if not isinstance(tags, list) or not all(isinstance(tag, str) for tag in tags):
                raise ValueError('tags must be a list of strings')
            result['tags'] = deepcopy(tags)
    if env is not None:
        if 'APP_ENDPOINT' in env:
            _validate_endpoint(env['APP_ENDPOINT'])
            result['endpoint'] = env['APP_ENDPOINT']
        if 'APP_ATTEMPTS' in env:
            attempts = env['APP_ATTEMPTS']
            if not isinstance(attempts, str) or not attempts.isdecimal():
                raise ValueError('APP_ATTEMPTS must be a decimal-digit string from 1 to 10')
            attempts = int(attempts)
            _validate_integer(attempts, 'APP_ATTEMPTS', 1, 10)
            result['retry']['attempts'] = attempts
    return result

