def _validate_layer(values, *, allowed, label):
    if not isinstance(values, dict):
        raise ValueError(f'{label} must be a dict')
    unknown = values.keys() - allowed
    if unknown:
        raise ValueError(f'unsupported {label} keys: {", ".join(sorted(map(str, unknown)))}')


def _validate_attempts(value):
    if isinstance(value, bool) or not isinstance(value, int) or not 1 <= value <= 10:
        raise ValueError('attempts must be an integer from 1 to 10')


def load_settings(overrides=None, env=None):
    """Return settings merged from defaults, explicit overrides, and env."""
    if overrides is None:
        overrides = {}
    _validate_layer(overrides, allowed={'endpoint', 'retry', 'tags'}, label='overrides')

    result = {
        'endpoint': DEFAULTS['endpoint'],
        'retry': DEFAULTS['retry'].copy(),
        'tags': DEFAULTS['tags'].copy(),
    }

    if 'endpoint' in overrides:
        endpoint = overrides['endpoint']
        if not isinstance(endpoint, str) or not endpoint:
            raise ValueError('endpoint must be a nonempty string')
        result['endpoint'] = endpoint

    if 'retry' in overrides:
        retry = overrides['retry']
        _validate_layer(retry, allowed={'attempts', 'delay_ms'}, label='retry overrides')
        if 'attempts' in retry:
            _validate_attempts(retry['attempts'])
            result['retry']['attempts'] = retry['attempts']
        if 'delay_ms' in retry:
            delay = retry['delay_ms']
            if isinstance(delay, bool) or not isinstance(delay, int) or not 0 <= delay <= 60000:
                raise ValueError('delay_ms must be an integer from 0 to 60000')
            result['retry']['delay_ms'] = delay

    if 'tags' in overrides:
        tags = overrides['tags']
        if not isinstance(tags, list) or any(not isinstance(tag, str) for tag in tags):
            raise ValueError('tags must be a list of strings')
        result['tags'] = tags.copy()

    if env is not None:
        if not hasattr(env, 'get'):
            raise ValueError('env must be a mapping')
        endpoint = env.get('APP_ENDPOINT')
        if endpoint is not None:
            if not isinstance(endpoint, str) or not endpoint:
                raise ValueError('APP_ENDPOINT must be a nonempty string')
            result['endpoint'] = endpoint
        attempts = env.get('APP_ATTEMPTS')
        if attempts is not None:
            if not isinstance(attempts, str) or not attempts.isascii() or not attempts.isdigit():
                raise ValueError('APP_ATTEMPTS must be a decimal-digit string')
            parsed_attempts = int(attempts)
            _validate_attempts(parsed_attempts)
            result['retry']['attempts'] = parsed_attempts

    return result

