from collections.abc import Mapping


DEFAULTS = {
    'endpoint': 'http://localhost',
    'retry': {'attempts': 3, 'delay_ms': 100},
    'tags': [],
}

_SUPPORTED_KEYS = {'endpoint', 'retry', 'tags'}
_RETRY_KEYS = {'attempts', 'delay_ms'}


def _validate_settings(settings):
    if not isinstance(settings['endpoint'], str) or not settings['endpoint']:
        raise ValueError('endpoint must be a nonempty string')

    retry = settings['retry']
    attempts = retry['attempts']
    delay_ms = retry['delay_ms']
    if type(attempts) is not int or not 1 <= attempts <= 10:
        raise ValueError('retry.attempts must be an integer from 1 to 10')
    if type(delay_ms) is not int or not 0 <= delay_ms <= 60000:
        raise ValueError('retry.delay_ms must be an integer from 0 to 60000')

    tags = settings['tags']
    if not isinstance(tags, list) or any(not isinstance(tag, str) for tag in tags):
        raise ValueError('tags must be a list of strings')


def load_settings(overrides=None, env=None):
    if overrides is not None and not isinstance(overrides, dict):
        raise ValueError('overrides must be a dict')
    if env is not None and not isinstance(env, Mapping):
        raise ValueError('env must be a mapping')

    overrides = {} if overrides is None else overrides
    env = {} if env is None else env
    unknown = overrides.keys() - _SUPPORTED_KEYS
    if unknown:
        raise ValueError(f'unsupported override keys: {list(unknown)!r}')

    result = {
        'endpoint': 'http://localhost',
        'retry': {'attempts': 3, 'delay_ms': 100},
        'tags': [],
    }
    for key, value in overrides.items():
        if key == 'retry':
            if not isinstance(value, dict):
                raise ValueError('retry override must be a dict')
            unknown_retry = value.keys() - _RETRY_KEYS
            if unknown_retry:
                raise ValueError(f'unsupported retry keys: {list(unknown_retry)!r}')
            result['retry'].update(value)
        elif key == 'tags':
            if not isinstance(value, list):
                raise ValueError('tags override must be a list')
            result[key] = list(value)
        else:
            result[key] = value

    if 'APP_ENDPOINT' in env:
        result['endpoint'] = env['APP_ENDPOINT']
    if 'APP_ATTEMPTS' in env:
        raw_attempts = env['APP_ATTEMPTS']
        if not isinstance(raw_attempts, str) or not raw_attempts.isascii() or not raw_attempts.isdigit():
            raise ValueError('APP_ATTEMPTS must contain decimal digits')
        result['retry']['attempts'] = int(raw_attempts)

    _validate_settings(result)
    return result

